  'tip.product.name': "रसीदों, POS उत्पाद सूची और रिपोर्ट में दिखने वाला नाम। वही नाम लिखें जो ग्राहक जानते हैं, जैसे 'बासमती चावल 1kg'।",
  'tip.product.category': 'यह उत्पाद किस समूह का है (जैसे शर्ट, किराना)। POS में उत्पाद फ़िल्टर करने और रिपोर्ट व्यवस्थित करने में उपयोगी।',
  'tip.product.supplier': 'आप यह उत्पाद किससे खरीदते हैं। वैकल्पिक — लेकिन आपूर्तिकर्ता जोड़ने से खरीद रिकॉर्ड करना और स्टॉक भरना तेज़ हो जाता है।',
  'tip.product.barcode': 'काउंटर पर स्कैन होने वाला और लेबल स्टिकर पर छपने वाला कोड। मौजूदा बारकोड स्कैन करें, टाइप करें, या Auto-Generate पर क्लिक करें।',
  'tip.product.costPrice': 'आप अपने आपूर्तिकर्ता से एक इकाई खरीदने के लिए कितना भुगतान करते हैं। लाभ की गणना में उपयोग होता है — ग्राहक इसे कभी नहीं देखते।',
  'tip.product.sellingPrice': 'ग्राहक एक इकाई के लिए कितना भुगतान करता है। Incl./Excl. टॉगल से बताएं कि दर्ज संख्या में GST पहले से शामिल है या नहीं।',
  'tip.product.gstRate': 'यह उत्पाद किस GST स्लैब में आता है। मानक स्लैब चुनें या Custom चुनें। यह रसीद और टैक्स रिपोर्ट पर कर तय करता है।',
  'tip.product.currentStock': 'अभी आपके पास कितनी इकाइयाँ हैं। बिक्री से यह स्वतः घटता है; खरीद और स्टॉक स्कैन से बढ़ता है।',
  'tip.product.lowStockThreshold': 'जब स्टॉक इस संख्या पर या इससे कम हो जाए, तो उत्पाद Low Stock अलर्ट में दिखता है ताकि आप दोबारा मंगवा सकें।',
  'tip.product.unit': 'यह उत्पाद कैसे मापा और बेचा जाता है — पीस, वज़न, आयतन, लंबाई, दर्जन या बॉक्स में।',

  'tip.category.name': "यह श्रेणी का नाम POS फ़िल्टर, उत्पाद पृष्ठ और रिपोर्ट में दिखता है। इसे छोटा रखें, जैसे 'शर्ट'।",
  'tip.category.parent': "वैकल्पिक — इसे उप-श्रेणी बनाने के लिए मौजूदा श्रेणी चुनें (जैसे 'शर्ट' के अंदर 'चेक्स')। शीर्ष-स्तर के लिए None छोड़ें।",

  'tip.supplier.name': 'वह विक्रेता या कंपनी जिससे आप स्टॉक खरीदते हैं। खरीद रिकॉर्ड करते समय और खरीद इतिहास में दिखता है।',
  'tip.supplier.phone': 'इस आपूर्तिकर्ता से संपर्क करने के लिए फ़ोन नंबर — ऑर्डर या डिलीवरी के बारे में बात करने हेतु उपयोगी।',
  'tip.supplier.email': 'वैकल्पिक — इस आपूर्तिकर्ता को खरीद ऑर्डर या प्रश्न भेजने के लिए ईमेल पता।',
  'tip.supplier.address': 'वैकल्पिक — आपूर्तिकर्ता का व्यवसाय पता, आपके अपने रिकॉर्ड के लिए।',
  'tip.supplier.gstin': 'वैकल्पिक — आपूर्तिकर्ता का GST पंजीकरण नंबर, टैक्स-अनुरूप खरीद रिकॉर्ड के लिए उपयोगी।',

  'tip.customer.name': 'ग्राहक का नाम, जो रसीदों, बिक्री इतिहास और चेकआउट पर चयन करते समय दिखता है।',
  'tip.customer.phone': 'WhatsApp रसीद और उधार रिमाइंडर भेजने, और चेकआउट पर इस ग्राहक को तुरंत खोजने के लिए उपयोग होता है।',
  'tip.customer.email': 'वैकल्पिक — इस ग्राहक का ईमेल पता, आपके संदर्भ के लिए रखा जाता है।',
  'tip.customer.address': 'वैकल्पिक — ग्राहक का पता, डिलीवरी या आपके अपने रिकॉर्ड के लिए।',

  'tip.expense.category': 'यह किस प्रकार का खर्च है (किराया, बिजली-पानी, वेतन, आदि) — खर्च पृष्ठ और P&L रिपोर्ट में खर्च को समूहित करने के लिए उपयोगी।',
  'tip.expense.amount': 'रुपयों में कितना खर्च हुआ। यह आपकी लाभ-हानि रिपोर्ट में राजस्व से घटाया जाता है।',
  'tip.expense.date': 'खर्च वास्तव में किस तारीख को हुआ — दैनिक/मासिक खर्च सारांश और रिपोर्ट के लिए उपयोग होता है।',
  'tip.expense.description': "वैकल्पिक — यह खर्च किसलिए था इसका संक्षिप्त नोट, जैसे 'मासिक बिजली बिल'।",
  'tip.expense.paymentMethod': 'आपने इस खर्च का भुगतान कैसे किया — नकद, बैंक ट्रांसफर, UPI या कार्ड।',
  'tip.expense.receipt': 'वैकल्पिक — इस खर्च के प्रमाण के रूप में रसीद या बिल की फोटो संलग्न करें।',

