  'tip.printer.showCustomerDetails': 'जब ज्ञात हो, रसीद पर ग्राहक का नाम और फोन नंबर प्रिंट करें।',
  'tip.printer.showBarcode': 'रसीद के नीचे इनवॉइस नंबर का स्कैन करने योग्य बारकोड प्रिंट करें।',
  'tip.printer.autoPrintOnSale': 'बिक्री पूरी होते ही बिना किसी मैनुअल क्लिक के रसीद को स्वतः प्रिंटर पर भेजें।',
  'tip.printer.cutPaper': 'हर रसीद के बाद कागज़ को स्वतः काटें — यह तभी काम करता है जब आपका प्रिंटर ऑटो-कट सपोर्ट करता हो।',
  'tip.printer.openCashDrawer': 'हर बिक्री के बाद जुड़े हुए कैश ड्रॉअर को खोलने का संकेत भेजें।',
  'tip.printer.labelPresets': 'तैयार लेबल लेआउट — अपने वर्तमान डिज़ाइन को तुरंत बदलने के लिए एक चुनें, फिर नीचे उसे अनुकूलित करें।',
  'tip.printer.labelMode': 'TSPL गैप सेंसर वाले समर्पित लेबल/स्टिकर प्रिंटर के लिए है (ज़्यादातर Xprinter/TSC/Gprinter मॉडल)। ESC/POS कॉम्पैक्ट सामान्य थर्मल रसीद प्रिंटर के लिए है जिन्हें छोटे लेबल प्रिंट करने के लिए उपयोग किया जाता है।',
  'tip.printer.labelOffset': 'अगर लेबल खिसका हुआ प्रिंट हो रहा है तो यह ठीक करें — सकारात्मक मान दाएं/नीचे शिफ्ट करते हैं, नकारात्मक बाएं/ऊपर।',
  'tip.printer.labelBarcodeOffset': 'यह ऊपर दिए गए ऑफ़सेट से अलग, केवल बारकोड की क्षैतिज सेंटरिंग को ठीक करता है। अलग-अलग प्रिंटर CODE128 को थोड़ा अलग तरीके से रेंडर करते हैं, इसलिए अगर सिर्फ बारकोड ऑफ-सेंटर दिखे तो इसे तब तक समायोजित करें जब तक यह सही न लगे।',
  'tip.printer.labelDirection': 'अगर लेबल उल्टे प्रिंट हो रहे हैं, तो प्रिंट को 180° घुमाने के लिए इसे चालू करें। आपको इसे चालू या बंद रखना है यह इस पर निर्भर करता है कि आपका स्टिकर रोल किस तरफ से लगा है।',
  'tip.printer.labelSize': 'आपके स्टिकर का सटीक आकार, मिलीमीटर में — यह आपके लगे हुए लेबल रोल से मेल खाना चाहिए वरना प्रिंट कट या गलत संरेखित हो जाएगा।',
  'tip.printer.labelBarcodeType': 'लेबल पर डिफ़ॉल्ट रूप से छपने वाला बारकोड प्रकार — CODE128 ज़्यादातर उत्पाद बारकोड के लिए उपयुक्त है, EAN13 13-अंकीय रिटेल बारकोड के लिए है, QR एक स्कैन करने योग्य वर्गाकार कोड है।',
  'tip.printer.previewProduct': 'नमूना डेटा के बजाय असली नाम, कीमत और बारकोड के साथ लेबल का पूर्वावलोकन करने के लिए एक असली उत्पाद चुनें।',
  'tip.printer.addElement': 'लेबल में कीमत, SKU, या कस्टम टेक्स्ट की एक पंक्ति जैसी कोई अन्य जानकारी जोड़ें।',
  'tip.printer.invoiceSize': 'ब्राउज़र से पूर्ण A4 इनवॉइस प्रिंट करते समय उपयोग किया जाने वाला कागज़ का आकार।',
  'tip.printer.invoiceTheme': 'प्रिंट किए गए A4 इनवॉइस पर हेडर और टोटल के लिए उपयोग किया जाने वाला रंग।',
  'tip.printer.invoiceTerms': 'A4 इनवॉइस के नीचे छपने वाला नियम व शर्तें टेक्स्ट, जैसे रिटर्न पॉलिसी या वारंटी जानकारी।',
  'tip.printer.invoiceShowHeader': 'इनवॉइस के ऊपर अपने व्यवसाय के नाम के साथ रंगीन हेडर बैनर दिखाएं।',
  'tip.printer.invoiceShowTerms': 'इनवॉइस के नीचे नियम व शर्तें टेक्स्ट प्रिंट करें।',
  'tip.printer.invoiceShowPaymentQR': 'ग्राहकों को सीधे इनवॉइस से भुगतान करने देने के लिए स्कैन करने योग्य UPI QR कोड प्रिंट करें।',

