  'tip.printer.labelPresets': 'तयार लेबल लेआउट — तुमची सध्याची रचना त्वरित बदलण्यासाठी एक निवडा, नंतर खाली ती सानुकूलित करा.',
  'tip.printer.labelMode': 'TSPL गॅप सेन्सर असलेल्या समर्पित लेबल/स्टिकर प्रिंटरसाठी आहे (बहुतेक Xprinter/TSC/Gprinter मॉडेल). ESC/POS कॉम्पॅक्ट लहान लेबल छापण्यासाठी वापरल्या जाणाऱ्या सामान्य थर्मल पावती प्रिंटरसाठी आहे.',
  'tip.printer.labelOffset': 'लेबल सरकून छापले जात असल्यास हे समायोजित करा — सकारात्मक मूल्ये उजवीकडे/खाली सरकवतात, नकारात्मक डावीकडे/वर.',
  'tip.printer.labelBarcodeOffset': 'हे फक्त बारकोडच्या क्षैतिज केंद्रीकरणाला दुरुस्त करते, वरील ऑफसेटपेक्षा वेगळे. वेगवेगळे प्रिंटर CODE128 थोडे वेगळे रेंडर करतात, त्यामुळे फक्त बारकोड ऑफ-सेंटर दिसत असल्यास, तो नीट होईपर्यंत हे समायोजित करा.',
  'tip.printer.labelDirection': 'लेबल उलटे छापले जात असल्यास, प्रिंट 180° फिरवण्यासाठी हे चालू करा. तुम्हाला हे चालू किंवा बंद ठेवायचे हे तुमचा स्टिकर रोल कोणत्या बाजूने बसवला आहे यावर अवलंबून आहे.',
  'tip.printer.labelSize': 'तुमच्या स्टिकरचा नेमका आकार, मिलिमीटरमध्ये — तो तुमच्या बसवलेल्या लेबल रोलशी जुळला पाहिजे अन्यथा प्रिंट कापली जाईल किंवा चुकीची जुळेल.',
  'tip.printer.labelBarcodeType': 'लेबलवर डीफॉल्टने छापला जाणारा बारकोड प्रकार — CODE128 बहुतेक उत्पादन बारकोडसाठी योग्य आहे, EAN13 13-अंकी रिटेल बारकोडसाठी आहे, QR स्कॅन करण्यायोग्य चौरस कोड आहे.',
  'tip.printer.previewProduct': 'नमुना डेटाऐवजी खऱ्या नाव, किंमत आणि बारकोडसह लेबलचे पूर्वावलोकन करण्यासाठी खरे उत्पादन निवडा.',
  'tip.printer.addElement': 'लेबलमध्ये किंमत, SKU, किंवा सानुकूल मजकूराची एक ओळ यासारखी आणखी माहिती जोडा.',
  'tip.printer.invoiceSize': 'ब्राउझरमधून पूर्ण A4 इनव्हॉइस छापताना वापरला जाणारा कागदाचा आकार.',
  'tip.printer.invoiceTheme': 'छापलेल्या A4 इनव्हॉइसवर हेडर आणि एकूण रकमेसाठी वापरला जाणारा रंग.',
  'tip.printer.invoiceTerms': 'A4 इनव्हॉइसच्या तळाशी छापला जाणारा अटी व शर्ती मजकूर, उदा. परतावा धोरण किंवा वॉरंटी माहिती.',
  'tip.printer.invoiceShowHeader': 'इनव्हॉइसच्या वर तुमच्या व्यवसायाच्या नावासह रंगीत हेडर बॅनर दाखवा.',
