  'pos.addProductManualHint': 'எந்த பொருளையும் கைமுறையாக சேர்க்கவும் — அல்லது பதிவு செய்யப்பட்ட பொருட்களை உடனடியாக சேர்க்க பார்கோடை ஸ்கேன் செய்யவும்',
