  'tip.tokenType.price': 'ప్రతిసారీ మీరే టైప్ చేసే మారుతున్న మొత్తానికి ఖాళీగా ఉంచండి (ఉదా. పార్కింగ్, QR బిల్లు). వన్-టాప్ జారీ చేయడానికి ధరను సెట్ చేయండి (ఉదా. చాయ్, సమోసా).',
