  'customers.totalSpent': 'કુલ ખર્ચ',

  'suppliers.addSupplier': 'સપ્લાયર ઉમેરો',

  'tip.product.name': "રસીદો, POS પ્રોડક્ટ ગ્રિડ અને રિપોર્ટ્સમાં દેખાતું નામ. ગ્રાહકો જે નામ જાણે છે તે જ વાપરો, દા.ત. 'બાસમતી ચોખા 1kg'.",
  'tip.product.category': 'આ પ્રોડક્ટ કયા ગ્રુપની છે (દા.ત. શર્ટ, કરિયાણું). POS માં પ્રોડક્ટ્સ ફિલ્ટર કરવા અને રિપોર્ટ્સ ગોઠવવા માટે વપરાય છે.',
  'tip.product.supplier': 'તમે આ પ્રોડક્ટ કોની પાસેથી ખરીદો છો. વૈકલ્પિક — પણ સપ્લાયર લિંક કરવાથી ખરીદી અને રિસ્ટોકિંગ ઝડપી બને છે.',
  'tip.product.barcode': 'કાઉન્ટર પર સ્કેન થતો અને લેબલ સ્ટીકર પર છપાતો કોડ. હાલનો બારકોડ સ્કેન કરો, ટાઇપ કરો, અથવા Auto-Generate પર ક્લિક કરો.',
  'tip.product.costPrice': 'તમે તમારા સપ્લાયર પાસેથી એક યુનિટ ખરીદવા માટે જે ચૂકવો છો. નફો ગણવા માટે વપરાય છે — ગ્રાહકો આ ક્યારેય જોતા નથી.',
  'tip.product.sellingPrice': 'ગ્રાહક એક યુનિટ માટે જે ચૂકવે છે. સંખ્યામાં GST પહેલેથી સામેલ છે કે નહીં તે કહેવા માટે Incl./Excl. ટોગલ વાપરો.',
  'tip.product.gstRate': 'આ પ્રોડક્ટ કયા GST સ્લેબમાં આવે છે. પ્રમાણભૂત સ્લેબ પસંદ કરો અથવા Custom પસંદ કરો. આ રસીદો અને ટેક્સ રિપોર્ટ પર ટેક્સ નક્કી કરે છે.',
  'tip.product.currentStock': 'હાલમાં તમારી પાસે કેટલા યુનિટ છે. વેચાણ તેને આપમેળે ઘટાડે છે; ખરીદી અને સ્ટોક સ્કેન તેને વધારે છે.',
  'tip.product.lowStockThreshold': 'સ્ટોક આ સંખ્યા અથવા તેનાથી નીચે જાય ત્યારે, ફરીથી ઓર્ડર કરવા માટે પ્રોડક્ટ Low Stock ચેતવણીઓમાં દેખાય છે.',
  'tip.product.unit': 'આ પ્રોડક્ટ કેવી રીતે માપવામાં અને વેચવામાં આવે છે — નંગ, વજન, જથ્થો, લંબાઈ, ડઝન અથવા બોક્સ પ્રમાણે.',

  'tip.category.name': "આ કેટેગરીનું નામ POS ફિલ્ટર્સ, પ્રોડક્ટ્સ પેજ અને રિપોર્ટ્સમાં દેખાય છે. ટૂંકું રાખો, દા.ત. 'શર્ટ'.",
  'tip.category.parent': "વૈકલ્પિક — આને સબ-કેટેગરી બનાવવા માટે હાલની કેટેગરી પસંદ કરો (દા.ત. 'શર્ટ' હેઠળ 'ચેક્સ'). ટોપ-લેવલ માટે None રાખો.",

  'tip.supplier.name': 'તમે જેની પાસેથી સ્ટોક ખરીદો છો તે વિક્રેતા અથવા કંપની. ખરીદી નોંધતી વખતે અને ખરીદી ઇતિહાસમાં દેખાય છે.',
  'tip.supplier.phone': 'ઓર્ડર અથવા ડિલિવરી વિશે સંપર્ક કરવા માટે આ સપ્લાયરનો સંપર્ક નંબર.',
  'tip.supplier.email': 'વૈકલ્પિક — આ સપ્લાયરને ખરીદી ઓર્ડર અથવા પ્રશ્નો મોકલવા માટે ઇમેઇલ સરનામું.',
  'tip.supplier.address': 'વૈકલ્પિક — સપ્લાયરનું વ્યવસાય સરનામું, તમારા પોતાના રેકોર્ડ માટે.',
  'tip.supplier.gstin': 'વૈકલ્પિક — સપ્લાયરનો GST નોંધણી નંબર, ટેક્સ-અનુપાલક ખરીદી રેકોર્ડ માટે ઉપયોગી.',

  'tip.customer.name': 'ગ્રાહકનું નામ, રસીદો પર, સેલ્સ હિસ્ટ્રીમાં અને ચેકઆઉટ પર પસંદ કરતી વખતે દેખાય છે.',
