  'tip.customer.email': 'વૈકલ્પિક — આ ગ્રાહક માટે ઇમેઇલ સરનામું, તમારા સંદર્ભ માટે રાખવામાં આવે છે.',
  'tip.customer.address': 'વૈકલ્પિક — ગ્રાહકનું સરનામું, ડિલિવરી અથવા તમારા પોતાના રેકોર્ડ માટે.',

  'tip.expense.category': 'આ કયા પ્રકારનો ખર્ચ છે (ભાડું, યુટિલિટીઝ, પગાર, વગેરે) — ખર્ચ અને P&L રિપોર્ટમાં ખર્ચને જૂથબદ્ધ કરવા માટે વપરાય છે.',
  'tip.expense.amount': 'રૂપિયામાં કેટલો ખર્ચ થયો. આ તમારા નફા-નુકસાન રિપોર્ટમાં આવકમાંથી બાદ કરવામાં આવે છે.',
  'tip.expense.date': 'ખર્ચ ખરેખર ક્યારે થયો તે તારીખ — દૈનિક/માસિક ખર્ચ સારાંશ અને રિપોર્ટ્સ માટે વપરાય છે.',
  'tip.expense.description': "વૈકલ્પિક — આ ખર્ચ શેના માટે હતો તેની ટૂંકી નોંધ, દા.ત. 'માસિક વીજળી બિલ'.",
  'tip.expense.paymentMethod': 'આ ખર્ચ માટે તમે કેવી રીતે ચૂકવણી કરી — રોકડ, બેંક ટ્રાન્સફર, UPI અથવા કાર્ડ.',
  'tip.expense.receipt': 'વૈકલ્પિક — આ ખર્ચના પુરાવા તરીકે રસીદ અથવા બિલનો ફોટો જોડો.',

  'tip.purchase.supplier': 'તમે આ ખરીદી કયા સપ્લાયર પાસેથી નોંધી રહ્યા છો. પ્રોડક્ટ્સ ઉમેરતા પહેલા જરૂરી.',
