  'tip.printer.cutPaper': 'દરેક રસીદ પછી કાગળ આપમેળે કાપો — આ ફક્ત ત્યારે જ કામ કરે છે જ્યારે તમારું પ્રિન્ટર ઓટો-કટને સપોર્ટ કરે.',
  'tip.printer.openCashDrawer': 'દરેક વેચાણ પછી જોડાયેલ કેશ ડ્રોઅર ખોલવા માટે સિગ્નલ મોકલો.',
  'tip.printer.labelPresets': 'તૈયાર લેબલ લેઆઉટ — તમારી વર્તમાન ડિઝાઇનને તરત બદલવા માટે એક પસંદ કરો, પછી નીચે તેને કસ્ટમાઇઝ કરો.',
  'tip.printer.labelMode': 'TSPL ગેપ સેન્સર ધરાવતા સમર્પિત લેબલ/સ્ટીકર પ્રિન્ટર માટે છે (મોટાભાગના Xprinter/TSC/Gprinter મોડેલ). ESC/POS કોમ્પેક્ટ નાના લેબલ છાપવા માટે વપરાતા સામાન્ય થર્મલ રસીદ પ્રિન્ટર માટે છે.',
  'tip.printer.labelOffset': 'જો લેબલ ખસીને છપાય રહ્યું હોય તો આને સમાયોજિત કરો — સકારાત્મક મૂલ્યો જમણે/નીચે ખસે છે, નકારાત્મક ડાબે/ઉપર.',
  'tip.printer.labelBarcodeOffset': 'આ ઉપરના ઓફસેટથી અલગ, ફક્ત બારકોડની આડી કેન્દ્રીકરણને સુધારે છે. વિવિધ પ્રિન્ટર CODE128 ને થોડું અલગ રીતે રેન્ડર કરે છે, તેથી જો ફક્ત બારકોડ કેન્દ્રથી હટેલો દેખાય, તો તે બરાબર થાય ત્યાં સુધી આને સમાયોજિત કરો.',
  'tip.printer.labelDirection': 'જો લેબલ ઊંધા છપાય રહ્યા હોય, તો પ્રિન્ટને 180° ફેરવવા માટે આને ચાલુ કરો. તમારે આને ચાલુ કે બંધ રાખવું તે તમારો સ્ટીકર રોલ કઈ બાજુ લગાવેલો છે તેના પર આધાર રાખે છે.',
  'tip.printer.labelSize': 'મિલિમીટરમાં તમારા સ્ટીકરનું ચોક્કસ કદ — તે તમારા લગાવેલા લેબલ રોલ સાથે મેળ ખાવું જોઈએ નહીં તો પ્રિન્ટ કપાઈ જશે અથવા ખોટી રીતે ગોઠવાશે.',
  'tip.printer.labelBarcodeType': 'લેબલ પર ડિફોલ્ટ રીતે છપાતો બારકોડ પ્રકાર — CODE128 મોટાભાગના પ્રોડક્ટ બારકોડ માટે યોગ્ય છે, EAN13 13-અંકના રિટેલ બારકોડ માટે છે, QR સ્કેન કરી શકાય તેવો ચોરસ કોડ છે.',
  'tip.printer.previewProduct': 'નમૂના ડેટાને બદલે વાસ્તવિક નામ, કિંમત અને બારકોડ સાથે લેબલનું પૂર્વાવલોકન કરવા માટે વાસ્તવિક પ્રોડક્ટ પસંદ કરો.',
  'tip.printer.addElement': 'લેબલમાં કિંમત, SKU, અથવા કસ્ટમ ટેક્સ્ટની લાઇન જેવી બીજી માહિતી ઉમેરો.',
  'tip.printer.invoiceSize': 'બ્રાઉઝરમાંથી સંપૂર્ણ A4 ઇનવોઇસ છાપતી વખતે વપરાતું કાગળનું કદ.',
  'tip.printer.invoiceTheme': 'છાપેલા A4 ઇનવોઇસ પર હેડર અને કુલ રકમો માટે વપરાતો રંગ.',
  'tip.printer.invoiceTerms': 'A4 ઇનવોઇસના તળિયે છપાતું નિયમો અને શરતોનું લખાણ, દા.ત. રિટર્ન પોલિસી અથવા વોરંટી માહિતી.',
  'tip.printer.invoiceShowHeader': 'ઇનવોઇસની ટોચ પર તમારા વ્યવસાયના નામ સાથે રંગીન હેડર બેનર બતાવો.',
  'tip.printer.invoiceShowTerms': 'ઇનવોઇસના તળિયે નિયમો અને શરતોનું લખાણ છાપો.',
