  'tip.product.category': 'এই পণ্যটি কোন গ্রুপের অন্তর্গত (যেমন শার্ট, মুদিখানা)। POS-এ পণ্য ফিল্টার করতে এবং রিপোর্ট সংগঠিত করতে ব্যবহৃত হয়।',
  'tip.product.supplier': 'আপনি এই পণ্যটি কার কাছ থেকে কেনেন। ঐচ্ছিক — তবে সরবরাহকারী লিঙ্ক করলে ক্রয় এবং পুনঃস্টক দ্রুত হয়।',
  'tip.product.barcode': 'কাউন্টারে স্ক্যান করা এবং লেবেল স্টিকারে ছাপা কোড। বিদ্যমান বারকোড স্ক্যান করুন, টাইপ করুন, বা Auto-Generate ক্লিক করুন।',
  'tip.product.costPrice': 'আপনার সরবরাহকারীর কাছ থেকে একটি ইউনিট কিনতে আপনি যা দেন। লাভ গণনা করতে ব্যবহৃত হয় — গ্রাহকরা এটি কখনো দেখেন না।',
  'tip.product.sellingPrice': 'গ্রাহক একটি ইউনিটের জন্য যা দেন। সংখ্যাটিতে GST ইতিমধ্যে অন্তর্ভুক্ত কিনা বলতে Incl./Excl. টগল ব্যবহার করুন।',
  'tip.product.gstRate': 'এই পণ্যটি কোন GST স্ল্যাবে পড়ে। একটি স্ট্যান্ডার্ড স্ল্যাব বেছে নিন বা Custom বেছে নিন। এটি রসিদ ও ট্যাক্স রিপোর্টে কর নির্ধারণ করে।',
  'tip.product.currentStock': 'এখন আপনার কাছে কত ইউনিট আছে। বিক্রয় এটি স্বয়ংক্রিয়ভাবে কমায়; ক্রয় এবং স্টক স্ক্যান এটি বাড়ায়।',
  'tip.product.lowStockThreshold': 'স্টক এই সংখ্যায় বা তার নিচে নামলে, পুনরায় অর্ডার করার জন্য পণ্যটি Low Stock সতর্কতায় দেখা যায়।',
  'tip.product.unit': 'এই পণ্যটি কীভাবে মাপা ও বিক্রি হয় — প্রতি পিস, ওজন, আয়তন, দৈর্ঘ্য, ডজন বা বাক্স অনুযায়ী।',

  'tip.category.name': "এই ক্যাটাগরির নাম POS ফিল্টার, পণ্য পৃষ্ঠা এবং রিপোর্টে দেখা যায়। সংক্ষিপ্ত রাখুন, যেমন 'শার্ট'.",
  'tip.category.parent': "ঐচ্ছিক — এটিকে সাব-ক্যাটাগরি করতে একটি বিদ্যমান ক্যাটাগরি বেছে নিন (যেমন 'শার্ট' এর অধীনে 'চেকস')। শীর্ষ-স্তরের জন্য None রাখুন।",

  'tip.supplier.name': 'আপনি যার কাছ থেকে স্টক কেনেন সেই বিক্রেতা বা কোম্পানি। ক্রয় নথিভুক্ত করার সময় এবং ক্রয় ইতিহাসে দেখা যায়।',
  'tip.supplier.phone': 'অর্ডার বা ডেলিভারি নিয়ে যোগাযোগ করতে এই সরবরাহকারীর জন্য একটি যোগাযোগ নম্বর।',
  'tip.supplier.email': 'ঐচ্ছিক — এই সরবরাহকারীকে ক্রয় আদেশ বা প্রশ্ন পাঠাতে একটি ইমেল ঠিকানা।',
  'tip.supplier.address': 'ঐচ্ছিক — সরবরাহকারীর ব্যবসায়িক ঠিকানা, আপনার নিজের রেকর্ডের জন্য।',
  'tip.supplier.gstin': 'ঐচ্ছিক — সরবরাহকারীর GST নিবন্ধন নম্বর, কর-সম্মত ক্রয় রেকর্ডের জন্য উপযোগী।',

  'tip.customer.name': 'গ্রাহকের নাম, রসিদে, বিক্রয় ইতিহাসে এবং চেকআউটে নির্বাচন করার সময় দেখা যায়।',
  'tip.customer.phone': 'WhatsApp রসিদ এবং ক্রেডিট রিমাইন্ডার পাঠাতে, এবং চেকআউটে এই গ্রাহককে দ্রুত খুঁজতে ব্যবহৃত হয়।',
  'tip.customer.email': 'ঐচ্ছিক — এই গ্রাহকের জন্য একটি ইমেল ঠিকানা, আপনার রেফারেন্সের জন্য রাখা হয়।',
