  'tip.expense.category': 'এটি কোন ধরনের খরচ (ভাড়া, ইউটিলিটি, বেতন, ইত্যাদি) — খরচ এবং P&L রিপোর্টে খরচ গোষ্ঠীভুক্ত করতে ব্যবহৃত হয়।',
  'tip.expense.amount': 'কত টাকা খরচ হয়েছে। এটি আপনার লাভ-ক্ষতি রিপোর্টে আয় থেকে বিয়োগ করা হয়।',
  'tip.expense.date': 'খরচটি প্রকৃতপক্ষে যে তারিখে হয়েছিল — দৈনিক/মাসিক খরচ সারাংশ এবং রিপোর্টের জন্য ব্যবহৃত হয়।',
  'tip.expense.description': "ঐচ্ছিক — এই খরচ কী জন্য ছিল তার একটি সংক্ষিপ্ত নোট, যেমন 'মাসিক বিদ্যুৎ বিল'.",
