  'tip.printer.cutPaper': 'প্রতিটি রসিদের পরে কাগজ স্বয়ংক্রিয়ভাবে কাটুন — এটি শুধুমাত্র তখনই কাজ করে যখন আপনার প্রিন্টার অটো-কাট সমর্থন করে।',
