  'tip.printer.labelMode': 'TSPL গ্যাপ সেন্সরযুক্ত ডেডিকেটেড লেবেল/স্টিকার প্রিন্টারের জন্য (বেশিরভাগ Xprinter/TSC/Gprinter মডেল)। ESC/POS কমপ্যাক্ট ছোট লেবেল প্রিন্ট করতে ব্যবহৃত সাধারণ থার্মাল রসিদ প্রিন্টারের জন্য।',
  'tip.printer.labelOffset': 'লেবেল সরে গিয়ে প্রিন্ট হলে এটি সামঞ্জস্য করুন — ধনাত্মক মান ডানে/নিচে সরায়, ঋণাত্মক বামে/উপরে।',
  'tip.printer.labelBarcodeOffset': 'এটি উপরের অফসেট থেকে আলাদাভাবে, শুধুমাত্র বারকোডের অনুভূমিক কেন্দ্রীকরণ ঠিক করে। বিভিন্ন প্রিন্টার CODE128 কে সামান্য ভিন্নভাবে রেন্ডার করে, তাই শুধু বারকোড কেন্দ্রের বাইরে দেখালে, এটি ঠিক না হওয়া পর্যন্ত সামঞ্জস্য করুন।',
  'tip.printer.labelDirection': 'লেবেল উল্টো প্রিন্ট হলে, প্রিন্টকে 180° ঘোরাতে এটি চালু করুন। আপনার স্টিকার রোল কোন দিকে লাগানো তার উপর নির্ভর করে আপনাকে এটি চালু বা বন্ধ রাখতে হবে।',
  'tip.printer.labelSize': 'মিলিমিটারে আপনার স্টিকারের সঠিক আকার — এটি আপনার লাগানো লেবেল রোলের সাথে মিলতে হবে নাহলে প্রিন্ট কাটা পড়বে বা ভুলভাবে সাজানো হবে।',
  'tip.printer.labelBarcodeType': 'লেবেলে ডিফল্টভাবে প্রিন্ট হওয়া বারকোড প্রকার — CODE128 বেশিরভাগ পণ্যের বারকোডের জন্য উপযুক্ত, EAN13 13-সংখ্যার রিটেইল বারকোডের জন্য, QR একটি স্ক্যানযোগ্য বর্গাকার কোড।',
  'tip.printer.previewProduct': 'নমুনা ডেটার পরিবর্তে প্রকৃত নাম, দাম এবং বারকোড দিয়ে লেবেল প্রিভিউ করতে একটি প্রকৃত পণ্য বেছে নিন।',
  'tip.printer.addElement': 'দাম, SKU, বা একটি কাস্টম টেক্সট লাইনের মতো লেবেলে আরও তথ্য যোগ করুন।',
  'tip.printer.invoiceSize': 'ব্রাউজার থেকে সম্পূর্ণ A4 ইনভয়েস প্রিন্ট করার সময় ব্যবহৃত কাগজের আকার।',
  'tip.printer.invoiceTheme': 'মুদ্রিত A4 ইনভয়েসে হেডার এবং মোটের জন্য ব্যবহৃত রঙ।',
  'tip.printer.invoiceTerms': 'A4 ইনভয়েসের নিচে মুদ্রিত শর্তাবলীর টেক্সট, যেমন রিটার্ন নীতি বা ওয়ারেন্টি তথ্য।',
