  'pos.addProductManualHint': 'ഏതെങ്കിലും ഉൽപ്പന്നം സ്വമേധയാ ചേർക്കുക — അല്ലെങ്കിൽ രജിസ്റ്റർ ചെയ്ത ഉൽപ്പന്നങ്ങൾ ഉടനടി ചേർക്കാൻ ബാർകോഡ് സ്കാൻ ചെയ്യുക',
