  'tip.purchase.supplier': 'നിങ്ങൾ ഈ വാങ്ങൽ ഏത് വിതരണക്കാരനിൽ നിന്നാണ് രേഖപ്പെടുത്തുന്നത്. ഉൽപ്പന്നങ്ങൾ ചേർക്കുന്നതിന് മുമ്പ് ആവശ്യമാണ്.',
  'tip.purchase.products': 'ഈ ഡെലിവറിയിൽ ലഭിച്ച ഓരോ ഉൽപ്പന്നവും അതിന്റെ അളവോടെ ചേർക്കുക — ഇത് അവയുടെ സ്റ്റോക്ക് ലെവലുകൾ സ്വയമേവ വർദ്ധിപ്പിക്കും.',

