  'tip.printer.paperWidth': 'ଆପଣଙ୍କ ଥର୍ମାଲ୍ ପେପର୍ ରୋଲର ପ୍ରକୃତ ଓସାର। ଅଧିକାଂଶ କମ୍ପାକ୍ଟ ପ୍ରିଣ୍ଟର୍ 58mm ବ୍ୟବହାର କରନ୍ତି; ଓସାର ରସିଦ ପ୍ରିଣ୍ଟର୍ 80mm ବ୍ୟବହାର କରନ୍ତି।',
  'tip.printer.printDestination': 'ପ୍ରିଣ୍ଟ କରିବା ସମୟରେ ରସିଦ କେଉଁଠାକୁ ପଠାଯାଏ — ଆପଣଙ୍କ ସଂଯୁକ୍ତ ବ୍ଲୁଟୁଥ୍ ପ୍ରିଣ୍ଟର୍, କିମ୍ବା ଆପଣଙ୍କ କମ୍ପ୍ୟୁଟରର ସାଧାରଣ ପ୍ରିଣ୍ଟ ଡାଏଲଗ୍।',
  'tip.printer.receiptDetails': 'ପ୍ରତ୍ୟେକ ରସିଦର ଉପରେ ମୁଦ୍ରିତ ହେଉଥିବା ବ୍ୟବସାୟ ବିବରଣୀ — କମ୍ପାନୀ ନାମ, GSTIN, ଠିକଣା, ଫୋନ୍, ଫୁଟର ବାର୍ତ୍ତା ଏବଂ ସର୍ତ୍ତାବଳୀ। ମୁଖ୍ୟ ସେଟିଂସ୍ ପୃଷ୍ଠା ସହିତ ସେୟାର୍ କରାଯାଇଛି।',
  'tip.printer.showLogo': 'ରସିଦର ଉପରେ ଆପଣଙ୍କ ଷ୍ଟୋର୍ ଲୋଗୋ ପ୍ରିଣ୍ଟ କରନ୍ତୁ।',
  'tip.printer.showGSTIN': 'ରସିଦରେ ଆପଣଙ୍କ GSTIN / କର ପଞ୍ଜୀକରଣ ନମ୍ବର ପ୍ରିଣ୍ଟ କରନ୍ତୁ।',
  'tip.printer.showCustomerDetails': 'ଜଣା ଥିଲେ, ରସିଦରେ ଗ୍ରାହକଙ୍କ ନାମ ଏବଂ ଫୋନ୍ ନମ୍ବର ପ୍ରିଣ୍ଟ କରନ୍ତୁ।',
  'tip.printer.showBarcode': 'ରସିଦର ତଳେ ଇନଭଏସ୍ ନମ୍ବରର ସ୍କାନ୍ କରାଯାଇପାରୁଥିବା ବାର୍‌କୋଡ୍ ପ୍ରିଣ୍ଟ କରନ୍ତୁ।',
  'tip.printer.autoPrintOnSale': 'ବିକ୍ରୟ ସମ୍ପୂର୍ଣ୍ଣ ହେବା ମାତ୍ରେ କୌଣସି ମାନୁଆଲ୍ କ୍ଲିକ୍ ବିନା ରସିଦକୁ ସ୍ୱୟଂଚାଳିତ ଭାବରେ ପ୍ରିଣ୍ଟରକୁ ପଠାନ୍ତୁ।',
  'tip.printer.cutPaper': 'ପ୍ରତ୍ୟେକ ରସିଦ ପରେ କାଗଜକୁ ସ୍ୱୟଂଚାଳିତ ଭାବରେ କାଟନ୍ତୁ — ଆପଣଙ୍କ ପ୍ରିଣ୍ଟର୍ ଅଟୋ-କଟ୍ ସପୋର୍ଟ କଲେ ହିଁ ଏହା କାମ କରେ।',
  'tip.printer.openCashDrawer': 'ପ୍ରତ୍ୟେକ ବିକ୍ରୟ ପରେ ସଂଯୁକ୍ତ କ୍ୟାସ୍ ଡ୍ରାୱାର୍ ଖୋଲିବାକୁ ସିଗନାଲ୍ ପଠାନ୍ତୁ।',
  'tip.printer.labelPresets': 'ପ୍ରସ୍ତୁତ ଲେବଲ୍ ଲେଆଉଟ୍ — ଆପଣଙ୍କ ବର୍ତ୍ତମାନର ଡିଜାଇନ୍‌କୁ ତୁରନ୍ତ ବଦଳାଇବାକୁ ଗୋଟିଏ ବାଛନ୍ତୁ, ତାପରେ ତଳେ ଏହାକୁ କଷ୍ଟମାଇଜ୍ କରନ୍ତୁ।',
  'tip.printer.labelMode': 'ଗ୍ୟାପ୍ ସେନ୍ସର୍ ଥିବା ପ୍ରତ୍ୟେକ ଲେବଲ୍/ଷ୍ଟିକର୍ ପ୍ରିଣ୍ଟର୍ ପାଇଁ TSPL (ଅଧିକାଂଶ Xprinter/TSC/Gprinter ମଡେଲ)। ଛୋଟ ଲେବଲ୍ ପ୍ରିଣ୍ଟ କରିବାକୁ ବ୍ୟବହୃତ ସାଧାରଣ ଥର୍ମାଲ୍ ରସିଦ ପ୍ରିଣ୍ଟର୍ ପାଇଁ ESC/POS କମ୍ପାକ୍ଟ।',
  'tip.printer.labelOffset': 'ଲେବଲ୍ ଖସିଯାଇ ପ୍ରିଣ୍ଟ ହେଉଥିଲେ ଏହାକୁ ସଜାଡନ୍ତୁ — ସକରାତ୍ମକ ମୂଲ୍ୟ ଡାହାଣ/ତଳକୁ ଘୁଞ୍ଚାଏ, ନକରାତ୍ମକ ବାମ/ଉପରକୁ।',
  'tip.printer.labelBarcodeOffset': 'ଏହା ଉପରର ଅଫସେଟ୍‌ଠାରୁ ଅଲଗା ଭାବରେ, କେବଳ ବାର୍‌କୋଡ୍‌ର ଭୂସମାନ୍ତର କେନ୍ଦ୍ରୀକରଣକୁ ସଜାଡ଼େ। ବିଭିନ୍ନ ପ୍ରିଣ୍ଟର୍ CODE128 କୁ ଟିକିଏ ଭିନ୍ନ ଭାବରେ ରେଣ୍ଡର୍ କରନ୍ତି, ତେଣୁ କେବଳ ବାର୍‌କୋଡ୍ କେନ୍ଦ୍ରରୁ ହଟିଥିବା ପରି ଦେଖାଗଲେ, ଏହା ଠିକ୍ ନ ହେବା ପର୍ଯ୍ୟନ୍ତ ଏହାକୁ ସଜାଡନ୍ତୁ।',
  'tip.printer.labelDirection': 'ଲେବଲ୍ ଓଲଟା ପ୍ରିଣ୍ଟ ହେଉଥିଲେ, ପ୍ରିଣ୍ଟକୁ 180° ଘୁରାଇବାକୁ ଏହାକୁ ଅନ୍ କରନ୍ତୁ। ଆପଣଙ୍କ ଷ୍ଟିକର୍ ରୋଲ୍ କେଉଁ ପାର୍ଶ୍ୱରେ ଲାଗିଛି ତାହା ଉପରେ ଆଧାର କରି ଏହାକୁ ଅନ୍ କିମ୍ବା ଅଫ୍ ରଖିବେ ବୋଲି ସ୍ଥିର ହୁଏ।',
  'tip.printer.labelSize': 'ମିଲିମିଟରରେ ଆପଣଙ୍କ ଷ୍ଟିକରର ସଠିକ୍ ଆକାର — ଏହା ଆପଣଙ୍କ ଲାଗିଥିବା ଲେବଲ୍ ରୋଲ୍ ସହିତ ମେଳ ଖାଇବା ଉଚିତ୍ ନଚେତ୍ ପ୍ରିଣ୍ଟ କଟିଯିବ କିମ୍ବା ଭୁଲ୍ ଭାବରେ ସଜାଡ଼ି ହେବ।',
  'tip.printer.labelBarcodeType': 'ଲେବଲ୍‌ରେ ଡିଫଲ୍ଟ୍ ଭାବରେ ପ୍ରିଣ୍ଟ ହେଉଥିବା ବାର୍‌କୋଡ୍ ପ୍ରକାର — CODE128 ଅଧିକାଂଶ ଉତ୍ପାଦ ବାର୍‌କୋଡ୍ ପାଇଁ ଉପଯୁକ୍ତ, EAN13 13-ଅଙ୍କ ରିଟେଲ୍ ବାର୍‌କୋଡ୍ ପାଇଁ, QR ଏକ ସ୍କାନ୍ କରାଯାଇପାରୁଥିବା ବର୍ଗାକାର କୋଡ୍।',
  'tip.printer.previewProduct': 'ନମୁନା ତଥ୍ୟ ପରିବର୍ତ୍ତେ ପ୍ରକୃତ ନାମ, ମୂଲ୍ୟ ଏବଂ ବାର୍‌କୋଡ୍ ସହିତ ଲେବଲ୍ ପ୍ରିଭ୍ୟୁ କରିବାକୁ ଏକ ପ୍ରକୃତ ଉତ୍ପାଦ ବାଛନ୍ତୁ।',
  'tip.printer.addElement': 'ମୂଲ୍ୟ, SKU, କିମ୍ବା କଷ୍ଟମ୍ ଟେକ୍ସଟ୍ ଧାଡିଭଳି ଆଉ ଏକ ସୂଚନା ଲେବଲ୍‌ରେ ଯୋଡନ୍ତୁ।',
  'tip.printer.invoiceSize': 'ବ୍ରାଉଜରରୁ ସମ୍ପୂର୍ଣ୍ଣ A4 ଇନଭଏସ୍ ପ୍ରିଣ୍ଟ କରିବା ସମୟରେ ବ୍ୟବହୃତ କାଗଜ ଆକାର।',
  'tip.printer.invoiceTheme': 'ପ୍ରିଣ୍ଟ ହୋଇଥିବା A4 ଇନଭଏସ୍‌ରେ ହେଡର୍ ଏବଂ ମୋଟ ପାଇଁ ବ୍ୟବହୃତ ରଙ୍ଗ।',
  'tip.printer.invoiceTerms': 'A4 ଇନଭଏସ୍‌ର ତଳେ ପ୍ରିଣ୍ଟ ହେଉଥିବା ସର୍ତ୍ତାବଳୀ ଟେକ୍ସଟ୍, ଯଥା ରିଟର୍ନ ନୀତି କିମ୍ବା ୱାରେଣ୍ଟି ସୂଚନା।',
  'tip.printer.invoiceShowHeader': 'ଇନଭଏସ୍‌ର ଉପରେ ଆପଣଙ୍କ ବ୍ୟବସାୟର ନାମ ସହିତ ରଙ୍ଗୀନ ହେଡର୍ ବ୍ୟାନର୍ ଦେଖାନ୍ତୁ।',
  'tip.printer.invoiceShowTerms': 'ଇନଭଏସ୍‌ର ତଳେ ସର୍ତ୍ତାବଳୀ ଟେକ୍ସଟ୍ ପ୍ରିଣ୍ଟ କରନ୍ତୁ।',
  'tip.printer.invoiceShowPaymentQR': 'ଗ୍ରାହକମାନେ ଇନଭଏସ୍‌ରୁ ସିଧାସଳଖ ଦେୟ ଦେଇପାରିବେ ପାଇଁ ସ୍କାନ୍ କରାଯାଇପାରୁଥିବା UPI QR କୋଡ୍ ପ୍ରିଣ୍ଟ କରନ୍ତୁ।',

